<h1>ابزارهای معرفی</h1>
<section class="card"><h2>اجرای سازگاری برای یک عضو</h2><form method="post" action="/admin/matches/run" class="grid two"><?= csrf_field() ?><label>عضو <select name="user_id" required><?php foreach ($users as $member): ?><option value="<?= (int)$member['id'] ?>"><?= e($member['first_name'].' '.$member['last_name'].' — '.$member['email']) ?></option><?php endforeach; ?></select></label><label class="check"><input type="checkbox" name="recalculate" value="1"> محاسبه دوباره جفت‌های موجود</label><button class="button">اجرای سازگاری</button></form></section>
<section class="card table-wrap"><h2>معرفی‌های اخیر</h2><table><thead><tr><th>شناسه</th><th>اعضا</th><th>وضعیت</th><th>امتیاز</th><th>اطمینان</th><th>اقدام مدیر</th></tr></thead><tbody><?php foreach ($matches as $match): ?><tr><td><?= (int)$match['id'] ?></td><td><?= e($match['user_one_name']) ?> ↔ <?= e($match['user_two_name']) ?></td><td><?= e(fa_label($match['match_status'])) ?></td><td><?= (int)round((float)$match['compatibility_score']) ?>%</td><td><?= (int)round((float)$match['confidence_score']) ?>%</td><td><a href="/admin/matches?match_id=<?= (int)$match['id'] ?>">دیدن امتیازها</a><form method="post" action="/admin/matches/reset" class="inline"><?= csrf_field() ?><input type="hidden" name="match_id" value="<?= (int)$match['id'] ?>"><label class="check"><input type="checkbox" name="clear_actions" value="1"> پاک‌کردن انتخاب‌ها</label><button>بازنشانی</button></form><form method="post" action="/admin/matches/recalculate" class="inline"><?= csrf_field() ?><input type="hidden" name="match_id" value="<?= (int)$match['id'] ?>"><button>محاسبه دوباره</button></form></td></tr><?php endforeach; ?></tbody></table></section>
<?php if ($selectedمعرفیId): ?><section class="card"><h2>توضیح معرفی شماره <?= (int)$selectedمعرفیId ?></h2><?php if ($explanation): ?><p><strong>دلیل:</strong> <?= e($explanation['why_matched']) ?></p><p><strong>نقاط قوت:</strong><br><?= nl2br(e($explanation['strongest_points'])) ?></p><p><strong>نیازمند گفت‌وگو:</strong><br><?= nl2br(e($explanation['caution_points'])) ?></p><?php endif; ?><div class="table-wrap"><table><thead><tr><th>نوع</th><th>امتیاز</th><th>وزن</th><th>جزئیات</th></tr></thead><tbody><?php foreach ($scores as $score): ?><tr><td><?= e($score['score_type']) ?></td><td><?= e((string)$score['score_value']) ?></td><td><?= e((string)$score['weight']) ?></td><td><?= e($score['details']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<section class="card table-wrap"><h2>جفت‌های مسدود</h2><table><thead><tr><th>مسدودکننده</th><th>مسدودشده</th><th>منبع</th><th>دلیل</th><th>زمان ایجاد</th></tr></thead><tbody><?php foreach ($blockedPairs as $block): ?><tr><td><?= e($block['blocker_name']) ?></td><td><?= e($block['blocked_name']) ?></td><td><?= e(fa_label($block['source'])) ?></td><td><?= e($block['reason_text']) ?></td><td><?= e($block['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></section>
